// ─── File: src/test/java/com/bank/cache/PutVsComputeTest.java ───
package com.bank.cache;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;

class PutVsComputeTest {

    AtomicInteger dbCalls = new AtomicInteger(0);

    String expensiveDbLookup(String key) {
        dbCalls.incrementAndGet();
        return "data-for-" + key;
    }

    // ═══ putIfAbsent: DB called EVERY time ═══
    @Test
    void putIfAbsent_eagerEvaluation() {
        Map<String, String> cache = new HashMap<>();
        dbCalls.set(0);

        for (int i = 0; i < 10; i++) {
            cache.putIfAbsent("SAV2001", expensiveDbLookup("SAV2001"));
        }

        assertThat(dbCalls.get()).isEqualTo(10);  // 10 DB calls! Wasteful!
        assertThat(cache.get("SAV2001")).isEqualTo("data-for-SAV2001");
    }

    // ═══ computeIfAbsent: DB called ONCE ═══
    @Test
    void computeIfAbsent_lazyEvaluation() {
        Map<String, String> cache = new HashMap<>();
        dbCalls.set(0);

        for (int i = 0; i < 10; i++) {
            cache.computeIfAbsent("SAV2001", k -> expensiveDbLookup(k));
        }

        assertThat(dbCalls.get()).isEqualTo(1);  // 1 DB call! Lazy!
        assertThat(cache.get("SAV2001")).isEqualTo("data-for-SAV2001");
    }

    // ═══ computeIfAbsent: grouping pattern ═══
    @Test
    void computeIfAbsent_grouping() {
        Map<String, List<String>> accountTrades = new HashMap<>();
        List.of("SAV2001:TRD1", "SAV2001:TRD2", "CUR3001:TRD3").forEach(entry -> {
            String[] parts = entry.split(":");
            accountTrades.computeIfAbsent(parts[0], k -> new ArrayList<>()).add(parts[1]);
        });

        assertThat(accountTrades.get("SAV2001")).containsExactly("TRD1", "TRD2");
        assertThat(accountTrades.get("CUR3001")).containsExactly("TRD3");
    }

    // ═══ computeIfAbsent in ConcurrentHashMap: atomic ═══
    @Test
    void concurrentHashMap_atomic() {
        ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
        dbCalls.set(0);

        // Even with multiple threads, function runs EXACTLY ONCE per key
        String result = cache.computeIfAbsent("SAV2001", k -> expensiveDbLookup(k));
        assertThat(result).isEqualTo("data-for-SAV2001");
        assertThat(dbCalls.get()).isEqualTo(1);
    }
}
